FRAMES = 10


class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 1          # current frame number (1-10)
        self.frame_rolls = []   # rolls made in the current frame
        self.complete = False

    def roll(self, pins):
        if self.complete:
            raise IndexError("cannot roll after game is over")
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("negative roll is invalid")
        if pins > MAX_PINS:
            raise ValueError("pin count exceeds pins on the lane")

        current = self.frame_rolls
        if self.frame < FRAMES:
            if current and current[0] + pins > MAX_PINS:
                raise ValueError("pin count exceeds pins on the lane")
            current.append(pins)
            if pins == MAX_PINS and len(current) == 1 or len(current) == 2:
                self.frame += 1
                self.frame_rolls = []
        else:
            self._validate_tenth(pins)
            current.append(pins)
            if len(current) == 3 or (len(current) == 2 and sum(current) < MAX_PINS):
                self.complete = True
        self.rolls.append(pins)

    def _validate_tenth(self, pins):
        current = self.frame_rolls
        if len(current) == 1:
            if current[0] < MAX_PINS and current[0] + pins > MAX_PINS:
                raise ValueError("pin count exceeds pins on the lane")
        elif len(current) == 2:
            first, second = current
            if first == MAX_PINS:
                # Two fill balls after a strike; pins reset only if second was a strike.
                if second < MAX_PINS and second + pins > MAX_PINS:
                    raise ValueError("invalid fill balls")
            elif first + second < MAX_PINS:
                raise IndexError("cannot throw bonus with an open tenth frame")

    def score(self):
        if not self.complete:
            raise IndexError("score cannot be taken until the end of the game")
        rolls = self.rolls
        total = 0
        i = 0
        for _ in range(FRAMES):
            if rolls[i] == MAX_PINS:
                total += MAX_PINS + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == MAX_PINS:
                total += MAX_PINS + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
